import java.util.*;

// ========== 纯责任链：多级审批 ==========
abstract class ApprovalHandler {
    protected ApprovalHandler next;
    protected int maxDays;
    protected String role;

    public ApprovalHandler(String role, int maxDays) {
        this.role = role;
        this.maxDays = maxDays;
    }

    // setNext 返回 next，支持链式组装：leader.setNext(manager).setNext(director)
    public ApprovalHandler setNext(ApprovalHandler next) {
        this.next = next;
        return next;
    }

    public void approve(int days) {
        if (days <= maxDays) {
            System.out.println(role + " 批准了 " + days + " 天假期");
        } else if (next != null) {
            System.out.println(role + " 无权处理 " + days + " 天，转交上级");
            next.approve(days);
        } else {
            // 链尾兜底：必须有终止逻辑，否则请求静默丢失
            throw new IllegalStateException(role + " 已是最高级，仍无法处理 " + days + " 天假期");
        }
    }
}

// ========== 不纯责任链：Filter 模拟 ==========
interface Filter {
    // 核心：doFilter 内部必须显式调 chain.doFilter 才会继续传递
    void doFilter(Map<String, Object> request, FilterChain chain);
}

class FilterChain {
    private List<Filter> filters = new ArrayList<>();
    private int index = 0;

    public void addFilter(Filter filter) { filters.add(filter); }

    public void doFilter(Map<String, Object> request) {
        if (index < filters.size()) {
            // index++ 保证每次调用推进到下一个 Filter
            filters.get(index++).doFilter(request, this);
        } else {
            System.out.println("到达 Controller 处理请求");
        }
    }
}

public class ChainOfResponsibilityDemo {
    public static void main(String[] args) {
        // --- 纯链演示 ---
        System.out.println("=== 纯责任链：多级审批 ===");
        ApprovalHandler leader = new ApprovalHandler("组长", 3);
        ApprovalHandler manager = new ApprovalHandler("经理", 7);
        ApprovalHandler director = new ApprovalHandler("总监", 15);
        // 链式组装：按权限升序
        leader.setNext(manager).setNext(director);

        leader.approve(2);   // 组长处理
        leader.approve(5);   // 转给经理
        leader.approve(10);  // 转给总监
        try {
            leader.approve(20); // 链尾兜底抛异常
        } catch (IllegalStateException e) {
            System.out.println("兜底：" + e.getMessage());
        }

        // --- 不纯链演示 ---
        System.out.println("\n=== 不纯责任链：Filter 链 ===");
        FilterChain chain = new FilterChain();
        chain.addFilter((req, c) -> {
            System.out.println("鉴权 Filter：检查 token");
            req.put("authenticated", true);
            c.doFilter(req); // 必须调用，否则后续 Filter 和 Controller 不执行
        });
        chain.addFilter((req, c) -> {
            System.out.println("限流 Filter：检查 QPS");
            c.doFilter(req);
        });
        chain.addFilter((req, c) -> {
            System.out.println("日志 Filter：记录请求");
            c.doFilter(req);
            System.out.println("日志 Filter：记录响应（逆序返回阶段）");
        });

        Map<String, Object> request = new HashMap<>();
        chain.doFilter(request);

        // --- 短路演示 ---
        System.out.println("\n=== 短路：鉴权失败不调 doFilter ===");
        FilterChain shortCircuit = new FilterChain();
        shortCircuit.addFilter((req, c) -> {
            System.out.println("鉴权 Filter：token 无效，不调 doFilter");
            // 不调 c.doFilter → 后续 Filter 和 Controller 都不执行
        });
        shortCircuit.addFilter((req, c) -> {
            System.out.println("这行不会执行");
            c.doFilter(req);
        });
        shortCircuit.doFilter(new HashMap<>());
    }
}
